-- =============================================================================
-- 0009 PERMISSION & MODULE CATALOG (GENERATED by scripts/gen-permission-catalog.mjs from
-- lib/permissions.ts and lib/modules.ts; do not hand-edit, regenerate instead)
-- Platform reference data used by effective_modules(), effective_permissions() and
-- seed_role_templates(). TS/SQL parity is asserted by lib/permissions.test.ts.
-- A CHANGED catalog must ship as a NEW generated migration, never by editing this one.
-- =============================================================================

create table module_catalog (
  key              text primary key,
  business_types   text[] not null,
  requires         text[],
  plan_feature     text,
  default_on_types text[]
);

create table permission_catalog (
  key                  text primary key,
  section              text not null,
  module_key           text references module_catalog (key),
  requires_profession  text[],
  store_scoped         boolean not null default false
);

create table role_templates (
  key          text primary key,
  name         text not null,
  home_route   text not null,
  seeded       boolean not null,
  permissions  text[] not null
);

-- Every template permission must exist in the catalog.
do $$ begin
  if exists (select 1 from role_templates t, unnest(t.permissions) p
              where p not in (select key from permission_catalog)) then
    raise exception 'role_templates reference unknown permission keys';
  end if;
end $$;

comment on table module_catalog     is 'Platform reference: modules (mirror of lib/modules.ts).';
comment on table permission_catalog is 'Platform reference: permission keys (mirror of lib/permissions.ts). requires_profession = clinical key, effective only with a verified credential.';
comment on table role_templates     is 'Platform reference: role templates copied into each tenant at provisioning (seeded = true) or offered when adding staff.';

alter table module_catalog     enable row level security;
alter table permission_catalog enable row level security;
alter table role_templates     enable row level security;
revoke insert, update, delete on module_catalog, permission_catalog, role_templates from service_role;
